const $=(s,e=document)=>e.querySelector(s), $$=(s,e=document)=>[...e.querySelectorAll(s)];
let db, page='dashboard', questionTab='batch', settingsTab='general', timer=null, remaining=0, timerMode='focus', toastTimer=null, saveChain=Promise.resolve();
let pomo={running:false,endAt:0,remaining:0,mode:'focus',subject:'',topic:'',focusMinutes:50,breakMinutes:10,completionId:''};
function loadPomo(){try{pomo={...pomo,...JSON.parse(localStorage.getItem('studyos-pomodoro')||'{}')}}catch{}pomo.focusMinutes=Math.min(480,Math.max(1,Number(pomo.focusMinutes)||50));pomo.breakMinutes=Math.min(120,Math.max(1,Number(pomo.breakMinutes)||10));pomo.endAt=Number(pomo.endAt)||0;pomo.remaining=Math.max(0,Number(pomo.remaining)||0);pomo.mode=pomo.mode==='break'?'break':'focus';pomo.running=Boolean(pomo.running&&pomo.endAt);timerMode=pomo.mode;remaining=pomo.running?Math.max(0,Math.ceil((pomo.endAt-Date.now())/1000)):pomo.remaining}
