 const ef=$('#examForm');if(ef)ef.onsubmit=async e=>{e.preventDefault();const x=fd(ef),scores={},scoreLabels={};db.subjects.forEach(s=>{scores[s.id]=Number(x['score_'+s.id])||0;scoreLabels[s.id]=s.name;delete x['score_'+s.id]});x.total=Number(x.total);x.correct=Number(x.correct);x.guessed=Number(x.guessed);if(!Number.isInteger(x.total)||x.total<1||!Number.isInteger(x.correct)||x.correct<0||!Number.isInteger(x.guessed)||x.guessed<0)return toast('Preencha as quantidades da prova com números inteiros válidos.');if(x.correct>x.total||x.guessed>x.correct)return toast('Acertos e chutes não podem superar os limites da prova.');if(Object.values(scores).some(value=>value<0||!Number.isInteger(value))||Object.values(scores).reduce((sum,value)=>sum+value,0)>x.correct)return toast('A soma dos acertos por matéria não pode superar o total de acertos.');db.exams.push({...x,scores,scoreLabels,id:Date.now()});await save();toast('Prova registrada!');render()};
