 const set=$('#settingsForm');if(set)set.onsubmit=async e=>{e.preventDefault();const x=fd(set);['cutoff','annualGoal','studyMinutes','breakMinutes'].forEach(k=>x[k]=Number(x[k]));x.userName=x.userName.trim();if(!x.userName)return toast('Digite seu nome.');if(!Number.isFinite(x.cutoff)||x.cutoff<1||x.cutoff>100||!Number.isInteger(x.annualGoal)||x.annualGoal<1||!Number.isInteger(x.studyMinutes)||x.studyMinutes<1||x.studyMinutes>480||!Number.isInteger(x.breakMinutes)||x.breakMinutes<1||x.breakMinutes>120)return toast('Revise os limites das configurações.');if(!db.settings.examTypes.includes(x.exam))x.exam=db.settings.examTypes[0];db.settings={...db.settings,...x};await save();updateProfile();toast('Configurações salvas!');render()};
