 $$('[data-exam-type]').forEach(b=>b.onclick=async()=>{const action=b.dataset.examType,name=b.dataset.name;if(action==='primary'){db.settings.exam=name;toast(`${name} definida como prova principal`)}if(action==='rename'){const next=prompt('Novo nome:',name);if(!next?.trim()||next.trim()===name)return;db.settings.examTypes=db.settings.examTypes.map(x=>x===name?next.trim():x);db.exams.forEach(x=>{if(x.type===name)x.type=next.trim()});if(db.settings.exam===name)db.settings.exam=next.trim();toast('Tipo de prova renomeado')}if(action==='delete'){if(db.settings.examTypes.length===1)return toast('Mantenha pelo menos um tipo de prova.');if(!confirm(`Excluir o tipo “${name}”? As provas já registradas serão preservadas.`))return;db.settings.examTypes=db.settings.examTypes.filter(x=>x!==name);if(db.settings.exam===name)db.settings.exam=db.settings.examTypes[0];toast('Tipo removido das opções')}await save();render()});
