 $$('[data-tree]').forEach(b=>b.onclick=async()=>{const action=b.dataset.tree,id=b.dataset.id,idx=+b.dataset.index;const a=db.knowledgeAreas.find(x=>x.id===id),s=db.subjects.find(x=>x.id===id);if(action==='add-subject'){const name=prompt('Nome da matéria:');if(name?.trim())db.subjects.push({id:'s'+Date.now(),areaId:id,name:name.trim(),color:['#6658d3','#159a83','#e59a52','#d96d55'][db.subjects.length%4],topics:[]})}if(action==='rename-area'){const name=prompt('Novo nome da categoria:',a.name);if(name?.trim())a.name=name.trim()}if(action==='delete-area'){const count=subjectsFor(id).length;if(!confirm(`Excluir “${a.name}” e suas ${count} matéria(s)? Os registros históricos serão mantidos.`))return;db.knowledgeAreas=db.knowledgeAreas.filter(x=>x.id!==id);db.subjects=db.subjects.filter(x=>x.areaId!==id)}if(action==='add-topic'){const name=prompt(`Novo assunto em ${s.name}:`);if(name?.trim())s.topics.push(name.trim())}if(action==='rename-subject'){const name=prompt('Novo nome da matéria:',s.name);if(name?.trim())s.name=name.trim()}if(action==='delete-subject'){if(!confirm(`Excluir a matéria “${s.name}” e seus assuntos? Os registros históricos serão mantidos.`))return;db.subjects=db.subjects.filter(x=>x.id!==id)}if(action==='rename-topic'){const name=prompt('Novo nome do assunto:',s.topics[idx]);if(name?.trim())s.topics[idx]=name.trim()}if(action==='delete-topic'){if(!confirm(`Excluir o assunto “${s.topics[idx]}”?`))return;s.topics.splice(idx,1)}await save();toast('Estrutura atualizada');render()});
