 const importer=$('#importData');if(importer)importer.onchange=async()=>{const file=importer.files?.[0];if(!file)return;if(file.size>8*1024*1024)return toast('O backup deve ter no máximo 8 MB.');try{const payload=JSON.parse(await file.text()),arrays=['knowledgeAreas','subjects','questionSessions','lessons','exams','essays','studySessions'];if(!payload||typeof payload!=='object'||!payload.settings||arrays.some(key=>!Array.isArray(payload[key])))throw new Error('estrutura inválida');localStorage.setItem('studyos-before-import',JSON.stringify(db));db=normalizeClientState(payload);await save();toast('Backup importado com sucesso');settingsTab='data';updateProfile();render()}catch(error){console.error(error);toast('Não foi possível importar: arquivo inválido.')}finally{importer.value=''}};
