function bindTimer(){if(!pomo.remaining&&!pomo.running){pomo.focusMinutes=db.settings.studyMinutes;pomo.breakMinutes=db.settings.breakMinutes;remaining=pomo.focusMinutes*60;pomo.remaining=remaining}timerMode=pomo.mode;$('#focusMinutes').value=pomo.focusMinutes;$('#breakMinutes').value=pomo.breakMinutes;if(pomo.subject&&db.subjects.some(item=>item.id===pomo.subject))$('#timerSubject').value=pomo.subject;else pomo.subject=$('#timerSubject').value;updateTimer();$('#toggleTimer').textContent=pomo.running?'Ⅱ Pausar':remaining<(timerMode==='focus'?pomo.focusMinutes:pomo.breakMinutes)*60?'▶ Continuar':'▶ Começar';$('#toggleTimer').onclick=()=>{if(pomo.running){remaining=Math.max(0,Math.ceil((pomo.endAt-Date.now())/1000));pomo.running=false;clearInterval(timer);timer=null;persistPomo();updateTimer();$('#toggleTimer').textContent='▶ Continuar'}else{pomo.subject=$('#timerSubject').value;if(!db.subjects.some(item=>item.id===pomo.subject))return toast('Escolha uma matéria válida.');pomo.focusMinutes=Math.min(480,Math.max(1,Number($('#focusMinutes').value)||50));pomo.breakMinutes=Math.min(120,Math.max(1,Number($('#breakMinutes').value)||10));if(!remaining)remaining=(timerMode==='focus'?pomo.focusMinutes:pomo.breakMinutes)*60;pomo.running=true;pomo.endAt=Date.now()+remaining*1000;persistPomo();ensurePomoTicker();$('#toggleTimer').textContent='Ⅱ Pausar'}};$('#timerSubject').onchange=e=>{pomo.subject=e.target.value;persistPomo()};$('#resetTimer').onclick=()=>{clearInterval(timer);timer=null;pomo.running=false;timerMode='focus';pomo.mode='focus';pomo.focusMinutes=Math.min(480,Math.max(1,Number($('#focusMinutes').value)||50));pomo.breakMinutes=Math.min(120,Math.max(1,Number($('#breakMinutes').value)||10));remaining=pomo.focusMinutes*60;pomo.remaining=remaining;persistPomo();updateTimer();$('#toggleTimer').textContent='▶ Começar'};$('#focusMinutes').onchange=async e=>{pomo.focusMinutes=Math.min(480,Math.max(1,Number(e.target.value)||50));e.target.value=pomo.focusMinutes;db.settings.studyMinutes=pomo.focusMinutes;if(!pomo.running&&timerMode==='focus')remaining=pomo.focusMinutes*60;persistPomo();updateTimer();await save()};$('#breakMinutes').onchange=async e=>{pomo.breakMinutes=Math.min(120,Math.max(1,Number(e.target.value)||10));e.target.value=pomo.breakMinutes;db.settings.breakMinutes=pomo.breakMinutes;persistPomo();await save()}}
function ensurePomoTicker(){if(timer)clearInterval(timer);if(pomo.running){timer=setInterval(tick,500);tick()}}
async function tick(){if(!pomo.running)return;remaining=Math.max(0,Math.ceil((pomo.endAt-Date.now())/1000));pomo.remaining=remaining;updateTimer();if(remaining>0)return;pomo.running=false;clearInterval(timer);timer=null;if(timerMode==='focus'){const completionId=`${pomo.endAt}-${pomo.subject}`;if(pomo.completionId!==completionId){pomo.completionId=completionId;const finished=new Date(),selectedSubject=subject(pomo.subject||db.subjects[0]?.id);db.studySessions.push({id:Date.now(),date:`${finished.getFullYear()}-${String(finished.getMonth()+1).padStart(2,'0')}-${String(finished.getDate()).padStart(2,'0')}`,subject:selectedSubject.id,subjectName:selectedSubject.name,topic:pomo.topic||'',minutes:pomo.focusMinutes});await save()}timerMode='break';pomo.mode='break';remaining=pomo.breakMinutes*60;toast('Sessão concluída! Hora de descansar.')}else{timerMode='focus';pomo.mode='focus';remaining=pomo.focusMinutes*60;toast('Intervalo concluído. Vamos voltar?')}pomo.remaining=remaining;persistPomo();updateTimer();const toggle=$('#toggleTimer');if(toggle)toggle.textContent='▶ Começar'}
function updateTimer(){if(pomo.running)remaining=Math.max(0,Math.ceil((pomo.endAt-Date.now())/1000));const m=Math.floor(remaining/60),s=remaining%60,text=$('#timerText');if(!text)return;text.textContent=`${String(m).padStart(2,'0')}:${String(s).padStart(2,'0')}`;$('#timerLabel').textContent=timerMode==='focus'?'FOCO':'INTERVALO';const total=(timerMode==='focus'?pomo.focusMinutes:pomo.breakMinutes)*60;$('#timerRing').style.setProperty('--timer',`${total?remaining/total*100:0}%`)}
function applyPalette(){document.body.dataset.palette=db.settings.palette||'violet'}
function updateProfile(){$('#profileName').textContent=db.settings.userName;const a=$('#avatar');if(db.settings.profilePhoto){const image=document.createElement('img');image.src=db.settings.profilePhoto;image.alt=`Foto de ${db.settings.userName}`;image.width=34;image.height=34;a.replaceChildren(image)}else a.textContent=db.settings.userName.charAt(0).toUpperCase();applyPalette()}
const compactHeatmap=heatmap;heatmap=function(){const weeks=26,activity={};db.studySessions.forEach(x=>{activity[x.date]??={minutes:0,questions:0};activity[x.date].minutes+=+x.minutes||0});db.questionSessions.forEach(x=>{activity[x.date]??={minutes:0,questions:0};activity[x.date].questions+=+x.total||0});const end=new Date(),monday=new Date(end);monday.setDate(end.getDate()-((end.getDay()+6)%7)-(weeks-1)*7);const months=[],cells=[];for(let w=0;w<weeks;w++){const first=new Date(monday);first.setDate(monday.getDate()+w*7);const month=first.toLocaleDateString('pt-BR',{month:'short'}).replace('.','');if(!months.length||months.at(-1).name!==month)months.push({name:month,col:w+2});for(let d=0;d<7;d++){const date=new Date(first);date.setDate(first.getDate()+d);const key=date.toISOString().slice(0,10),a=activity[key]||{minutes:0,questions:0},score=a.minutes/25+a.questions/10,level=score?Math.min(4,Math.max(1,Math.ceil(score/2))):0,future=date>end,label=`${date.toLocaleDateString('pt-BR')}: ${a.minutes} min · ${a.questions} questões`;cells.push(`<button class="heat ${level?'l'+level:''} ${future?'future':''}" style="grid-column:${w+2};grid-row:${d+2}" title="${label}" aria-label="${label}"></button>`)}}return `<div class="heatmap-scroll"><div class="heatmap-shell heatmap-wide"><div class="heat-months">${months.map(m=>`<span style="grid-column:${m.col}">${m.name}</span>`).join('')}</div><div class="heatmap">${['S','T','Q','Q','S','S','D'].map((d,i)=>`<span class="day" style="grid-row:${i+2}">${d}</span>`).join('')}${cells.join('')}</div><div class="heat-footer"><span>Últimos 6 meses</span><span class="heat-scale">Menos <i></i><i class="l1"></i><i class="l2"></i><i class="l3"></i><i class="l4"></i> Mais</span></div></div></div>`};
var selectedHeatmapMonth=localDateValue().slice(0,7);heatmap=function(){const activity={};db.studySessions.forEach(x=>{activity[x.date]??={minutes:0,questions:0};activity[x.date].minutes+=+x.minutes||0});db.questionSessions.forEach(x=>{activity[x.date]??={minutes:0,questions:0};activity[x.date].questions+=+x.total||0});const [year,month]=selectedHeatmapMonth.split('-').map(Number),firstDay=new Date(year,month-1,1),lastDay=new Date(year,month,0),start=new Date(firstDay),offset=(firstDay.getDay()+6)%7;start.setDate(firstDay.getDate()-offset);const weeks=Math.ceil((offset+lastDay.getDate())/7),cells=[];for(let w=0;w<weeks;w++)for(let d=0;d<7;d++){const date=new Date(start);date.setDate(start.getDate()+w*7+d);const localKey=localDateValue(date),a=activity[localKey]||{minutes:0,questions:0},score=a.minutes/25+a.questions/10,level=score?Math.min(4,Math.max(1,Math.ceil(score/2))):0,out=date.getMonth()!==month-1,label=`${date.toLocaleDateString('pt-BR')}: ${a.minutes} min · ${a.questions} questões`;cells.push(`<button class="heat ${level?'l'+level:''} ${out?'outside':''}" style="grid-column:${w+2};grid-row:${d+2}" title="${label}" aria-label="${label}"></button>`)}const monthOptions=Array.from({length:12},(_,i)=>{const d=new Date();d.setDate(1);d.setMonth(d.getMonth()-i);const value=localDateValue(d).slice(0,7),label=d.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});return `<option value="${value}" ${value===selectedHeatmapMonth?'selected':''}>${label}</option>`}).join('');return `<div class="heatmap-month-view"><div class="heatmap-toolbar"><span>Atividade no período</span><select id="heatmapMonth" aria-label="Selecionar mês">${monthOptions}</select></div><div class="heatmap-shell" style="--heat-weeks:${weeks}"><div class="heatmap month-grid">${['S','T','Q','Q','S','S','D'].map((d,i)=>`<span class="day" style="grid-row:${i+2}">${d}</span>`).join('')}${cells.join('')}</div><div class="heat-footer"><span>${lastDay.getDate()} dias no mês</span><span class="heat-scale">Menos <i></i><i class="l1"></i><i class="l2"></i><i class="l3"></i><i class="l4"></i> Mais</span></div></div></div>`};
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&pomo.running)tick()});window.addEventListener('storage',e=>{if(e.key==='studyos-pomodoro'){loadPomo();if(pomo.running)ensurePomoTicker();updateTimer()}});document.addEventListener('click',e=>{const b=e.target.closest('[data-page]');if(b){page=b.dataset.page;$('.sidebar').classList.remove('open');$('#mobileMenu')?.setAttribute('aria-expanded','false');render()}});$('#themeBtn').onclick=()=>document.body.classList.toggle('dark');$('#mobileMenu').onclick=()=>{const open=$('.sidebar').classList.toggle('open');$('#mobileMenu').setAttribute('aria-expanded',String(open))};
window.addEventListener('DOMContentLoaded',async()=>{try{const response=await fetch('/api/data');if(!response.ok)throw new Error(`Erro ${response.status}`);const raw=await response.json(),before=JSON.stringify(raw);db=normalizeClientState(raw);if(JSON.stringify(db)!==before)await save();loadPomo();updateProfile();render();if(pomo.running)ensurePomoTicker();window.dispatchEvent(new Event('studyos:ready'))}catch(error){console.error(error);$('#app').innerHTML='<div class="card empty"><h2>Não foi possível carregar o StudyOS</h2><p>Abra o sistema pelo arquivo <b>iniciar.bat</b> e tente novamente.</p></div>'}});
